<script setup>
import { computed, ref, watch } from 'vue'
import { objectRequest, objectWrite, objectIdentityKey } from '../../data-object-api.js'
const props=defineProps({modelValue:Boolean,sources:Array,directories:Array,selectedDirectory:Number})
const emit=defineEmits(['update:modelValue','registered'])
const sourceId=ref(null),directoryId=ref(null),catalog=ref(''),schema=ref(''),tables=ref([]),chosen=ref([]),keyword=ref(''),step=ref(0),loading=ref(false),error=ref(''),result=ref(null)
const fieldRows=ref([]),fieldOpen=ref(false),fieldTitle=ref('')
async function showFields(t){try{fieldRows.value=await objectWrite('/api/data-objects/discovery-fields','POST',{sourceId:sourceId.value,catalog:t.catalog,schema:t.schema,table:t.name,type:t.type});fieldTitle.value=t.name;fieldOpen.value=true}catch(e){error.value=e.message}}
const source=computed(()=>props.sources.find(s=>s.id===sourceId.value))
const visible=computed(()=>tables.value.filter(t=>[t.name,t.schema,t.catalog].some(v=>String(v||'').toLowerCase().includes(keyword.value.toLowerCase()))))
watch(()=>props.modelValue,open=>{if(open){sourceId.value=null;directoryId.value=props.selectedDirectory||null;catalog.value='';schema.value='';tables.value=[];chosen.value=[];keyword.value='';step.value=0;error.value='';result.value=null}})
function sourceChanged(){catalog.value=source.value?.type==='MYSQL'?source.value.database:'';schema.value='';tables.value=[];chosen.value=[]}
async function discover(){if(!sourceId.value){error.value='请选择数据源';return}try{loading.value=true;error.value='';const q=new URLSearchParams({sourceId:String(sourceId.value)});if(catalog.value.trim())q.set('catalog',catalog.value.trim());if(schema.value.trim())q.set('schema',schema.value.trim());tables.value=await objectRequest(`/api/data-objects/discovery?${q}`);chosen.value=[]}catch(e){error.value=e.message}finally{loading.value=false}}
function next(){if(!directoryId.value||!chosen.value.length){error.value='请选择目标目录和至少一个物理对象';return}error.value='';chosen.value=chosen.value.map(t=>({...t,displayName:t.displayName||t.name,description:t.description||''}));step.value=1}
async function submit(){try{loading.value=true;error.value='';const objects=chosen.value.map(t=>({directoryId:directoryId.value,identity:{sourceId:sourceId.value,catalog:t.catalog,schema:t.schema,table:t.name,type:t.type},name:t.displayName,description:t.description}));result.value=await objectWrite('/api/data-objects/register','POST',{objects});emit('registered')}catch(e){error.value=e.message}finally{loading.value=false}}
</script>
<template><el-dialog :model-value="modelValue" title="注册数据对象" width="min(950px,96vw)" @update:model-value="emit('update:modelValue',$event)"><el-alert v-if="error" :title="error" type="error" show-icon closable @close="error=''"/><el-steps :active="step" finish-status="success" simple><el-step title="选择物理对象"/><el-step title="填写对象信息"/></el-steps><template v-if="step===0"><div class="filters"><el-select v-model="sourceId" placeholder="选择数据源" filterable @change="sourceChanged"><el-option v-for="s in sources" :key="s.id" :value="s.id" :label="s.name"/></el-select><el-select v-model="directoryId" placeholder="选择对象目录"><el-option v-for="d in directories" :key="d.id" :value="d.id" :label="d.label"/></el-select><el-input v-model="catalog" placeholder="数据库 / catalog"/><el-input v-model="schema" placeholder="模式 / schema（可选）"/><el-button type="primary" :loading="loading" @click="discover">读取物理表</el-button></div><el-input v-model="keyword" placeholder="搜索已读取的表" clearable/><el-table :data="visible" max-height="380" :row-key="t=>objectIdentityKey({...t,sourceId,table:t.name})" @selection-change="chosen=$event"><el-table-column type="selection" width="45"/><el-table-column prop="catalog" label="数据库"/><el-table-column prop="schema" label="模式"/><el-table-column prop="name" label="对象名称"/><el-table-column prop="type" label="类型"/><el-table-column label="字段"><template #default="s"><el-button link type="primary" @click="showFields(s.row)">查看字段</el-button></template></el-table-column></el-table></template><template v-else><el-table :data="chosen" max-height="380" :row-key="t=>objectIdentityKey({...t,sourceId,table:t.name})"><el-table-column prop="name" label="物理表名"/><el-table-column prop="type" label="类型" width="90"/><el-table-column label="对象中文名"><template #default="scope"><el-input v-model="scope.row.displayName" maxlength="200"/></template></el-table-column><el-table-column label="描述"><template #default="scope"><el-input v-model="scope.row.description" maxlength="1000"/></template></el-table-column></el-table><el-table v-if="result" :data="result" max-height="200"><el-table-column label="对象"><template #default="scope">{{ scope.row.identity?.table }}</template></el-table-column><el-table-column label="结果"><template #default="scope">{{ scope.row.success ? '注册成功' : scope.row.error }}</template></el-table-column></el-table></template><template #footer><el-button @click="emit('update:modelValue',false)">关闭</el-button><el-button v-if="step===1&&!result" @click="step=0">上一步</el-button><el-button v-if="step===0" type="primary" @click="next">下一步</el-button><el-button v-else-if="!result" type="primary" :loading="loading" @click="submit">注册</el-button></template></el-dialog><el-dialog v-model="fieldOpen" :title="fieldTitle+' 的字段'" width="min(850px,96vw)" append-to-body><el-table :data="fieldRows" max-height="400"><el-table-column prop="name" label="字段"/><el-table-column prop="type" label="类型"/><el-table-column prop="length" label="长度"/><el-table-column prop="scale" label="精度"/><el-table-column prop="nullable" label="可空"/><el-table-column prop="primaryKey" label="主键"/><el-table-column prop="remarks" label="注释"/></el-table></el-dialog></template>
<style scoped>.filters{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}.filters>*{flex:1 1 150px;min-width:0}.el-table{margin-top:12px}</style>
